content.css:
.mc-host {
  position: relative;
  overflow: hidden;
  width: 100%;
  height: 100%;
  background: #06070a;
}
.mc-stage-root {
  position: absolute;
  left: 0;
  top: 0;
  transform-origin: 0 0;
}
.mc-app {
  position: absolute;
  inset: 0;
  outline: none;
  color: var(--mc-text);
  background: var(--mc-bg);
  font-family: "Segoe UI", "Inter", system-ui, -apple-system, sans-serif;
  font-size: var(--mc-fs, 13px);
  line-height: 1.4;
  -webkit-font-smoothing: antialiased;
  font-variant-numeric: tabular-nums;
}
.mc-app *,
.mc-app *::before,
.mc-app *::after {
  box-sizing: border-box;
}
.mc-app button {
  font: inherit;
  color: inherit;
}
.mc-app h1,
.mc-app h2,
.mc-app h3,
.mc-app h4 {
  margin: 0;
  font-weight: 600;
}
.mc-app h4 {
  font-size: 0.92em;
  color: var(--mc-soft);
  margin: 10px 0 4px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}
.mc-app ::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}
.mc-app ::-webkit-scrollbar-thumb {
  background: var(--mc-line2);
  border-radius: 8px;
}
.mc-app ::-webkit-scrollbar-track {
  background: transparent;
}
.mc-app :focus-visible {
  outline: 2px solid var(--mc-accent);
  outline-offset: 2px;
  border-radius: 6px;
}
.mc-theme-dark {
  background: radial-gradient(1200px 600px at 60% -10%, rgba(255, 197, 61, 0.07), transparent 60%), radial-gradient(900px 500px at 100% 100%, rgba(45, 212, 191, 0.04), transparent 60%), var(--mc-bg);
}
.mc-theme-light {
  background: radial-gradient(1200px 600px at 60% -10%, rgba(183, 121, 31, 0.08), transparent 60%), var(--mc-bg);
}
:where(.mc-app) button {
  background: transparent;
  border: 0;
  padding: 0;
  color: inherit;
  text-align: inherit;
  cursor: pointer;
}
:where(.mc-app) button.mc-ins-row {
  width: 100%;
  text-align: left;
  padding: 7px 8px;
  border-radius: 8px;
}
:where(.mc-app) button.mc-ins-row.mc-on {
  background: color-mix(in srgb, var(--mc-accent) 14%, transparent);
  box-shadow: inset 3px 0 0 var(--mc-accent);
}
.mc-empty-app {
  display: grid;
  place-items: center;
  height: 100%;
  color: var(--mc-muted);
}
.mc-frame {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
}
.mc-header {
  display: flex;
  align-items: center;
  gap: 16px;
  height: 58px;
  padding: 0 18px;
  border-bottom: 1px solid var(--mc-line);
  background: var(--mc-glass);
  backdrop-filter: blur(14px);
  flex: none;
}
.mc-brand {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 214px;
}
.mc-logo {
  width: 32px;
  height: 32px;
  filter: drop-shadow(0 0 8px color-mix(in srgb, var(--mc-accent) 55%, transparent));
}
.mc-logo rect {
  fill: var(--mc-accent);
}
.mc-brand-name {
  font-weight: 800;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  font-size: 1.05em;
}
.mc-brand-sub {
  color: var(--mc-muted);
  font-size: 0.78em;
  letter-spacing: 0.04em;
}
.mc-search {
  flex: 1;
  max-width: 560px;
  display: flex;
  align-items: center;
  gap: 10px;
  height: 38px;
  padding: 0 12px;
  border-radius: 10px;
  cursor: pointer;
  background: var(--mc-panel);
  border: 1px solid var(--mc-line2);
  color: var(--mc-muted);
  text-align: left;
  transition: border-color 0.2s cubic-bezier(0.22, 1, 0.36, 1), box-shadow 0.2s cubic-bezier(0.22, 1, 0.36, 1);
}
.mc-search span {
  flex: 1;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}
.mc-search:hover {
  border-color: color-mix(in srgb, var(--mc-accent) 50%, transparent);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--mc-accent) 12%, transparent);
}
kbd {
  font-family: inherit;
  font-size: 0.78em;
  padding: 2px 6px;
  border-radius: 5px;
  border: 1px solid var(--mc-line2);
  background: var(--mc-panel2);
  color: var(--mc-soft);
  white-space: nowrap;
}
.mc-header-right {
  margin-left: auto;
  display: flex;
  align-items: center;
  gap: 10px;
}
.mc-theme-switch {
  display: flex;
  padding: 3px;
  border-radius: 10px;
  background: var(--mc-panel);
  border: 1px solid var(--mc-line);
}
.mc-theme-switch .mc-icon-btn {
  width: 30px;
  height: 28px;
}
.mc-theme-switch .mc-on {
  background: var(--mc-accent);
  color: #111;
}
.mc-bell {
  position: relative;
}
.mc-bell .mc-badge {
  position: absolute;
  top: -4px;
  right: -6px;
}
.mc-profile {
  display: flex;
  align-items: center;
  gap: 8px;
  padding-left: 10px;
  border-left: 1px solid var(--mc-line);
}
.mc-avatar {
  width: 34px;
  height: 34px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: linear-gradient(135deg, var(--mc-accent), var(--mc-accent2));
  color: #111;
}
.mc-avatar-sm {
  width: 24px;
  height: 24px;
  font-size: 0.7em;
  border-radius: 50%;
  display: inline-grid;
  place-items: center;
  background: var(--mc-panel3);
  color: var(--mc-soft);
  flex: none;
  font-weight: 700;
}
.mc-profile-name {
  font-weight: 600;
}
.mc-profile-role {
  color: var(--mc-muted);
  font-size: 0.8em;
}
.mc-ribbon {
  display: flex;
  align-items: center;
  gap: 6px;
  height: 40px;
  padding: 0 14px;
  border-bottom: 1px solid var(--mc-line);
  background: var(--mc-bg2);
  flex: none;
  overflow: hidden;
}
.mc-ribbon .mc-select {
  height: 28px;
}
.mc-rib-item {
  display: flex;
  align-items: center;
  gap: 6px;
  height: 28px;
  padding: 0 10px;
  border-radius: 8px;
  border: 1px solid transparent;
  background: transparent;
  cursor: pointer;
  white-space: nowrap;
  color: var(--mc-soft);
}
.mc-rib-item b {
  color: var(--mc-text);
}
.mc-rib-item:hover:not(:disabled) {
  background: var(--mc-panel);
  border-color: var(--mc-line);
}
.mc-rib-item:disabled {
  cursor: default;
}
.mc-rib-item.mc-tone-good b {
  color: var(--mc-good);
}
.mc-rib-item.mc-tone-warn b {
  color: var(--mc-warn);
}
.mc-rib-item.mc-tone-bad b {
  color: var(--mc-bad);
}
.mc-rib-label {
  color: var(--mc-muted);
  font-size: 0.85em;
}
.mc-rib-spacer {
  flex: 1;
}
.mc-body {
  flex: 1;
  display: flex;
  min-height: 0;
}
.mc-side {
  width: 228px;
  flex: none;
  display: flex;
  flex-direction: column;
  gap: 1px;
  padding: 8px 10px 10px;
  border-right: 1px solid var(--mc-line);
  background: var(--mc-glass);
  overflow-y: auto;
  transition: width 0.28s cubic-bezier(0.22, 1, 0.36, 1);
}
.mc-side-top {
  display: flex;
  justify-content: flex-end;
}
.mc-side-group {
  margin: 10px 8px 3px;
  color: var(--mc-muted);
  font-size: 0.7em;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  white-space: nowrap;
}
.mc-nav {
  position: relative;
  display: flex;
  align-items: center;
  gap: 10px;
  height: 32px;
  padding: 0 10px;
  border: 0;
  border-radius: 9px;
  background: transparent;
  color: var(--mc-soft);
  cursor: pointer;
  text-align: left;
  white-space: nowrap;
  transition: background 0.18s cubic-bezier(0.22, 1, 0.36, 1), color 0.18s cubic-bezier(0.22, 1, 0.36, 1), transform 0.18s cubic-bezier(0.22, 1, 0.36, 1);
}
.mc-nav:hover {
  background: var(--mc-panel2);
  color: var(--mc-text);
  transform: translateX(2px);
}
.mc-nav .mc-badge {
  margin-left: auto;
}
.mc-nav-label {
  overflow: hidden;
  text-overflow: ellipsis;
}
.mc-nav-on {
  color: var(--mc-accent);
  background: linear-gradient(90deg, color-mix(in srgb, var(--mc-accent) 18%, transparent), transparent);
}
.mc-nav-on::before {
  content: "";
  position: absolute;
  left: -10px;
  top: 6px;
  bottom: 6px;
  width: 3px;
  border-radius: 3px;
  background: var(--mc-accent);
  box-shadow: 0 0 10px var(--mc-accent);
}
.mc-side-foot {
  margin-top: auto;
  padding: 12px 8px 0;
  color: var(--mc-muted);
  font-size: 0.8em;
  display: flex;
  flex-direction: column;
  gap: 6px;
  border-top: 1px solid var(--mc-line);
}
.mc-live {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--mc-good);
}
.mc-live-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--mc-good);
  box-shadow: 0 0 8px var(--mc-good);
}
.mc-side-slogan {
  color: var(--mc-accent);
  font-weight: 600;
  font-size: 1.05em;
  line-height: 1.3;
}
.mc-side-collapsed .mc-side {
  width: 60px;
  padding: 8px 6px;
}
.mc-side-collapsed .mc-nav-label,
.mc-side-collapsed .mc-side-group,
.mc-side-collapsed .mc-side-foot,
.mc-side-collapsed .mc-nav .mc-badge {
  display: none;
}
.mc-side-collapsed .mc-nav {
  justify-content: center;
  padding: 0;
}
.mc-side-collapsed .mc-side-top {
  justify-content: center;
}
.mc-stage {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
}
.mc-crumbs {
  display: flex;
  align-items: center;
  gap: 8px;
  height: 38px;
  padding: 0 18px;
  flex: none;
  color: var(--mc-muted);
  font-size: 0.86em;
}
.mc-crumb-on {
  color: var(--mc-text);
  font-weight: 600;
}
.mc-crumb-period {
  margin-left: auto;
}
.mc-outlet {
  flex: 1;
  overflow: auto;
  padding: 4px 18px 22px;
  display: flex;
  flex-direction: column;
  gap: var(--mc-gap);
}
.mc-enter > * {
  animation: mc-rise 0.42s cubic-bezier(0.22, 1, 0.36, 1) both;
}
.mc-enter > *:nth-child(2) {
  animation-delay: 0.04s;
}
.mc-enter > *:nth-child(3) {
  animation-delay: 0.08s;
}
.mc-enter > *:nth-child(4) {
  animation-delay: 0.12s;
}
.mc-enter > *:nth-child(n+5) {
  animation-delay: 0.16s;
}
.mc-page-title {
  display: flex;
  align-items: baseline;
  gap: 12px;
  flex-wrap: wrap;
  padding-top: 4px;
}
.mc-page-title h1 {
  font-size: 1.5em;
  letter-spacing: 0.01em;
}
.mc-page-title .mc-muted {
  max-width: 820px;
}
.mc-page-toolbar,
.mc-filters {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}
.mc-push {
  margin-left: auto;
}
.mc-row-gap {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}
.mc-wrap {
  flex-wrap: wrap;
}
.mc-col,
.mc-col-stack {
  display: flex;
  flex-direction: column;
  gap: var(--mc-gap);
  min-width: 0;
}
.mc-grid {
  display: grid;
  gap: var(--mc-gap);
  min-width: 0;
}
.mc-grid > * {
  min-width: 0;
}
.mc-g-2 {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}
.mc-g-3 {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}
.mc-g-4 {
  grid-template-columns: repeat(4, minmax(0, 1fr));
}
.mc-g-graph {
  grid-template-columns: minmax(0, 1fr) 320px;
}
.mc-g-explorer {
  grid-template-columns: 240px minmax(0, 1fr);
  align-items: start;
}
.mc-g-assist {
  grid-template-columns: minmax(0, 1fr) 340px;
}
.mc-g-collab {
  grid-template-columns: 300px minmax(0, 1fr);
}
.mc-g-detective {
  grid-template-columns: minmax(0, 1.3fr) minmax(0, 1fr);
}
.mc-g-terminal {
  grid-template-columns: 300px minmax(0, 1fr);
}
.mc-g-wi {
  grid-template-columns: 330px minmax(0, 1fr);
  align-items: start;
}
.mc-span-2 {
  grid-column: span 2;
}
.mc-muted {
  color: var(--mc-muted);
}
.mc-small {
  font-size: 0.86em;
}
.mc-accent {
  color: var(--mc-accent);
}
.mc-num {
  text-align: right;
  font-variant-numeric: tabular-nums;
}
.mc-dim {
  opacity: 0.55;
}
.mc-click {
  cursor: pointer;
}
.mc-big {
  font-size: 1.1em;
}
.mc-grow {
  flex: 1;
}
.mc-h160 {
  height: 160px;
}
.mc-h180 {
  height: 180px;
}
.mc-h200 {
  height: 200px;
}
.mc-h220 {
  height: 220px;
}
.mc-h260 {
  height: 260px;
}
.mc-h280 {
  height: 280px;
}
.mc-h300 {
  height: 300px;
}
.mc-chart {
  width: 100%;
  min-height: 120px;
  position: relative;
}
.mc-pre {
  white-space: pre-wrap;
  font-family: Consolas, monospace;
  font-size: 0.85em;
  background: var(--mc-panel2);
  padding: 10px;
  border-radius: 8px;
  border: 1px solid var(--mc-line);
  max-height: 260px;
  overflow: auto;
}
.mc-hint {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  padding: 9px 12px;
  border-radius: 10px;
  background: color-mix(in srgb, var(--mc-info) 9%, transparent);
  border: 1px solid color-mix(in srgb, var(--mc-info) 25%, transparent);
  color: var(--mc-soft);
  font-size: 0.88em;
}
.mc-hint svg {
  flex: none;
  margin-top: 2px;
  color: var(--mc-info);
}
.mc-li {
  display: flex;
  gap: 6px;
  align-items: flex-start;
  padding: 3px 0;
}
.mc-li svg {
  margin-top: 3px;
  flex: none;
  color: var(--mc-accent);
}
.mc-link {
  background: none;
  border: 0;
  padding: 0;
  color: var(--mc-info);
  cursor: pointer;
  text-decoration: underline;
  text-decoration-color: transparent;
  transition: text-decoration-color 0.2s;
}
.mc-link:hover {
  text-decoration-color: currentColor;
}
.mc-card {
  position: relative;
  display: flex;
  flex-direction: column;
  min-width: 0;
  border-radius: 14px;
  border: 1px solid var(--mc-line);
  background: linear-gradient(180deg, color-mix(in srgb, var(--mc-panel2) 92%, transparent), var(--mc-panel));
  box-shadow: var(--mc-shadow);
  transition: border-color 0.25s cubic-bezier(0.22, 1, 0.36, 1), transform 0.25s cubic-bezier(0.22, 1, 0.36, 1), box-shadow 0.25s cubic-bezier(0.22, 1, 0.36, 1);
}
.mc-card::before {
  content: "";
  position: absolute;
  inset: 0 0 auto 0;
  height: 1px;
  border-radius: 14px 14px 0 0;
  background: linear-gradient(90deg, transparent, color-mix(in srgb, var(--mc-accent) 45%, transparent), transparent);
  opacity: 0.6;
  pointer-events: none;
}
.mc-card:hover {
  border-color: color-mix(in srgb, var(--mc-accent) 22%, var(--mc-line));
}
.mc-card-head {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: var(--mc-pad) var(--mc-pad) 6px;
  flex-wrap: wrap;
  min-height: 20px;
}
.mc-card-title {
  display: flex;
  align-items: center;
  gap: 8px;
  font-weight: 600;
  letter-spacing: 0.02em;
}
.mc-card-title svg {
  color: var(--mc-accent);
}
.mc-card-sub {
  color: var(--mc-muted);
  font-size: 0.82em;
  flex: 1 1 200px;
}
.mc-card-actions {
  margin-left: auto;
  display: flex;
  gap: 6px;
  align-items: center;
  flex-wrap: wrap;
}
.mc-card-actions:empty {
  display: none;
}
.mc-card-body {
  padding: 4px var(--mc-pad) var(--mc-pad);
  display: flex;
  flex-direction: column;
  gap: 8px;
  min-width: 0;
  flex: 1;
}
.mc-card-danger {
  border-color: color-mix(in srgb, var(--mc-bad) 40%, transparent);
  background: linear-gradient(160deg, color-mix(in srgb, var(--mc-bad) 12%, var(--mc-panel)), var(--mc-panel));
}
.mc-stat-card {
  padding: 12px 14px;
  border-radius: 12px;
  border: 1px solid var(--mc-line);
  background: var(--mc-panel);
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.mc-stat-card span {
  color: var(--mc-muted);
  font-size: 0.85em;
}
.mc-stat-card b {
  font-size: 1.45em;
}
.mc-stat-card.mc-tone-good b {
  color: var(--mc-good);
}
.mc-stat-card.mc-tone-warn b {
  color: var(--mc-warn);
}
.mc-stat-card.mc-tone-bad b {
  color: var(--mc-bad);
}
.mc-stat-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(110px, 1fr));
  gap: 8px;
}
.mc-stat {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 10px;
  border-radius: 10px;
  background: var(--mc-panel2);
  border: 1px solid var(--mc-line);
  text-align: left;
  cursor: pointer;
  transition: transform 0.2s cubic-bezier(0.22, 1, 0.36, 1), border-color 0.2s;
}
.mc-stat span {
  color: var(--mc-muted);
  font-size: 0.82em;
}
.mc-stat b {
  font-size: 1.25em;
}
.mc-stat svg {
  color: var(--mc-accent);
}
.mc-stat:hover {
  transform: translateY(-2px);
  border-color: var(--mc-line2);
}
.mc-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 32px;
  padding: 0 12px;
  border-radius: 9px;
  cursor: pointer;
  border: 1px solid var(--mc-line2);
  background: var(--mc-panel2);
  white-space: nowrap;
  font-weight: 500;
  transition: transform 0.16s cubic-bezier(0.34, 1.56, 0.64, 1), background 0.2s, border-color 0.2s, box-shadow 0.2s;
}
.mc-btn:hover:not(:disabled) {
  border-color: color-mix(in srgb, var(--mc-accent) 45%, transparent);
  transform: translateY(-1px);
}
.mc-btn:active:not(:disabled) {
  transform: scale(0.97);
}
.mc-btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}
.mc-btn-sm {
  height: 27px;
  padding: 0 9px;
  font-size: 0.88em;
  border-radius: 8px;
}
.mc-btn-primary {
  background: linear-gradient(180deg, var(--mc-accent), var(--mc-accent2));
  color: #15120a;
  border-color: transparent;
  font-weight: 600;
  box-shadow: 0 6px 18px color-mix(in srgb, var(--mc-accent) 30%, transparent);
}
.mc-btn-primary:hover:not(:disabled) {
  box-shadow: 0 8px 24px color-mix(in srgb, var(--mc-accent) 45%, transparent);
}
.mc-btn-ghost {
  background: transparent;
  border-color: transparent;
  color: var(--mc-soft);
}
.mc-btn-danger {
  background: color-mix(in srgb, var(--mc-bad) 14%, transparent);
  border-color: color-mix(in srgb, var(--mc-bad) 40%, transparent);
  color: var(--mc-bad);
}
.mc-icon-btn {
  display: inline-grid;
  place-items: center;
  width: 32px;
  height: 32px;
  border-radius: 9px;
  border: 1px solid transparent;
  background: transparent;
  color: var(--mc-soft);
  cursor: pointer;
  transition: background 0.2s, color 0.2s, transform 0.16s cubic-bezier(0.34, 1.56, 0.64, 1);
}
.mc-icon-btn:hover {
  background: var(--mc-panel2);
  color: var(--mc-text);
}
.mc-icon-btn:active {
  transform: scale(0.92);
}
.mc-icon-btn.mc-on {
  color: var(--mc-accent);
}
.mc-chip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  height: 22px;
  padding: 0 9px;
  border-radius: 999px;
  font-size: 0.78em;
  font-weight: 600;
  white-space: nowrap;
  border: 1px solid currentColor;
  background: color-mix(in srgb, currentColor 10%, transparent);
