  fill: var(--mc-soft);
  font-size: 10px;
  pointer-events: none;
}
.mc-node:hover circle {
  stroke: var(--mc-text);
}
.mc-node-dim {
  opacity: 0.22;
}
.mc-node-focus circle {
  stroke: var(--mc-accent);
  stroke-width: 3;
}
.mc-node-path circle {
  stroke: var(--mc-accent);
  stroke-width: 2.5;
}
.mc-path {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
}
.mc-depgraph {
  width: 100%;
  height: 360px;
}
.mc-dep-edge {
  stroke: var(--mc-line2);
  fill: none;
  stroke-width: 1.4;
}
.mc-dep-node {
  cursor: pointer;
}
.mc-dep-node rect {
  fill: var(--mc-panel2);
  stroke: var(--mc-line2);
  rx: 8;
}
.mc-dep-node text {
  fill: var(--mc-text);
  font-size: 10.5px;
}
.mc-dep-node .mc-dep-val {
  fill: var(--mc-accent);
  font-weight: 700;
}
.mc-dep-node.mc-on rect {
  stroke: var(--mc-accent);
  stroke-width: 2;
  fill: color-mix(in srgb, var(--mc-accent) 15%, var(--mc-panel2));
}
.mc-dep-node.mc-up rect {
  stroke: var(--mc-info);
}
.mc-dep-node.mc-down rect {
  stroke: var(--mc-teal);
}
.mc-datatable {
  display: flex;
  flex-direction: column;
  gap: 8px;
  min-width: 0;
}
.mc-table-tools {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}
.mc-table-count {
  color: var(--mc-muted);
  font-size: 0.84em;
  margin-left: auto;
}
.mc-table-scroll {
  overflow: auto;
  max-height: 520px;
  border-radius: 10px;
  border: 1px solid var(--mc-line);
}
.mc-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.9em;
}
.mc-table th {
  position: sticky;
  top: 0;
  z-index: 1;
  text-align: left;
  padding: 8px 10px;
  background: var(--mc-panel3);
  color: var(--mc-soft);
  font-weight: 600;
  white-space: nowrap;
  cursor: pointer;
  user-select: none;
}
.mc-table th svg {
  vertical-align: middle;
  margin-left: 3px;
  color: var(--mc-accent);
}
.mc-table th.mc-num {
  text-align: right;
}
.mc-table td {
  padding: 7px 10px;
  border-top: 1px solid var(--mc-line);
  max-width: 340px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.mc-table tbody tr {
  transition: background 0.15s;
}
.mc-table tbody tr:hover {
  background: var(--mc-panel2);
}
.mc-row-on {
  background: color-mix(in srgb, var(--mc-accent) 12%, transparent) !important;
}
.mc-col-chooser {
  position: relative;
}
.mc-col-chooser summary {
  list-style: none;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 30px;
  padding: 0 10px;
  border-radius: 9px;
  border: 1px solid var(--mc-line2);
  cursor: pointer;
  background: var(--mc-panel2);
}
.mc-col-chooser summary::-webkit-details-marker {
  display: none;
}
.mc-col-list {
  position: absolute;
  right: 0;
  top: 34px;
  z-index: 20;
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 8px 10px;
  min-width: 200px;
  max-height: 300px;
  overflow: auto;
  border-radius: 10px;
  border: 1px solid var(--mc-line2);
  background: var(--mc-panel);
  box-shadow: var(--mc-shadow);
}
.mc-col-list label {
  display: flex;
  gap: 6px;
  align-items: center;
  white-space: nowrap;
  cursor: pointer;
}
.mc-pager {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
  color: var(--mc-muted);
  font-size: 0.86em;
}
.mc-kv {
  display: flex;
  flex-direction: column;
  margin: 0;
}
.mc-kv-row {
  display: grid;
  grid-template-columns: 160px 1fr;
  gap: 10px;
  padding: 5px 0;
  border-bottom: 1px solid var(--mc-line);
  word-break: break-word;
}
dl.mc-kv {
  display: grid;
  grid-template-columns: 170px 1fr;
  gap: 6px 10px;
}
dl.mc-kv dt {
  color: var(--mc-muted);
}
dl.mc-kv dd {
  margin: 0;
}
.mc-global-res {
  display: flex;
  flex-direction: column;
  gap: 6px;
  max-height: 200px;
  overflow: auto;
}
.mc-global-group {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: baseline;
}
.mc-tabs {
  display: inline-flex;
  gap: 2px;
  padding: 3px;
  border-radius: 11px;
  background: var(--mc-panel);
  border: 1px solid var(--mc-line);
  flex-wrap: wrap;
  align-self: flex-start;
}
.mc-tab {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 28px;
  padding: 0 12px;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: var(--mc-soft);
  cursor: pointer;
  white-space: nowrap;
  transition: background 0.22s cubic-bezier(0.22, 1, 0.36, 1), color 0.22s;
}
.mc-tab:hover {
  color: var(--mc-text);
}
.mc-tab-on {
  background: color-mix(in srgb, var(--mc-accent) 18%, var(--mc-panel2));
  color: var(--mc-accent);
  font-weight: 600;
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--mc-accent) 35%, transparent);
}
.mc-tab-count {
  font-size: 0.78em;
  padding: 0 6px;
  border-radius: 999px;
  background: var(--mc-panel3);
  color: var(--mc-soft);
}
.mc-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  padding: 26px 12px;
  color: var(--mc-muted);
  text-align: center;
}
.mc-empty svg {
  opacity: 0.6;
}
.mc-skeleton {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.mc-skel-line {
  height: 12px;
  border-radius: 6px;
  background: linear-gradient(90deg, var(--mc-panel2), var(--mc-panel3), var(--mc-panel2));
  background-size: 200% 100%;
  animation: mc-shimmer 1.4s linear infinite;
}
.mc-error-box {
  display: flex;
  gap: 12px;
  padding: 16px;
  border-radius: 12px;
  border: 1px solid color-mix(in srgb, var(--mc-bad) 45%, transparent);
  background: color-mix(in srgb, var(--mc-bad) 10%, transparent);
  color: var(--mc-text);
}
.mc-error-box svg {
  color: var(--mc-bad);
}
.mc-error {
  color: var(--mc-bad);
  font-size: 0.8em;
}
.mc-invalid .mc-input,
.mc-invalid .mc-select,
.mc-invalid .mc-textarea,
.mc-invalid select {
  border-color: var(--mc-bad);
}
.mc-ins-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 7px 4px;
  border-bottom: 1px solid var(--mc-line);
  min-width: 0;
}
.mc-ins-row > span:first-child {
  overflow: hidden;
  text-overflow: ellipsis;
}
.mc-ins-row.mc-click {
  border-radius: 6px;
  transition: background 0.15s;
}
.mc-ins-row.mc-click:hover {
  background: var(--mc-panel2);
}
.mc-ins-list {
  display: flex;
  flex-direction: column;
}
.mc-ins-section {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 10px 0;
  border-bottom: 1px solid var(--mc-line);
}
.mc-ins-title {
  font-weight: 600;
  color: var(--mc-soft);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  font-size: 0.78em;
}
.mc-inspector {
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.mc-note {
  padding: 8px 10px;
  border-radius: 8px;
  background: var(--mc-panel2);
  border-left: 3px solid var(--mc-accent);
  font-size: 0.9em;
}
.mc-why {
  padding: 10px 12px;
  border-radius: 10px;
  background: color-mix(in srgb, var(--mc-accent) 8%, transparent);
  border: 1px solid color-mix(in srgb, var(--mc-accent) 25%, transparent);
}
.mc-cite {
  display: inline-flex;
  font-size: 0.75em;
  padding: 1px 6px;
  border-radius: 6px;
  background: var(--mc-panel3);
  color: var(--mc-soft);
  margin: 2px 3px 0 0;
}
.mc-legend {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  font-size: 0.82em;
  color: var(--mc-soft);
  align-items: center;
}
.mc-dot-legend {
  display: inline-block;
  width: 9px;
  height: 9px;
  border-radius: 3px;
  margin-right: 5px;
  vertical-align: -1px;
  flex: none;
}
.mc-dot-legend.mc-ring-task {
  background: transparent;
  border: 2px solid var(--mc-info);
  border-radius: 50%;
}
.mc-dot-legend.mc-ring-inc {
  background: transparent;
  border: 2px solid var(--mc-bad);
  border-radius: 50%;
}
.mc-dot,
.mc-sev-dot {
  display: inline-block;
  width: 9px;
  height: 9px;
  border-radius: 50%;
  flex: none;
}
.mc-score {
  display: inline-grid;
  place-items: center;
  min-width: 34px;
  height: 24px;
  padding: 0 6px;
  border-radius: 7px;
  font-weight: 700;
  font-size: 0.86em;
  background: color-mix(in srgb, var(--mc-accent) 16%, transparent);
  color: var(--mc-accent);
}
.mc-score-parts {
  display: flex;
  gap: 4px;
  flex-wrap: wrap;
  font-size: 0.78em;
  color: var(--mc-muted);
}
.mc-queue-row,
.mc-task-row,
.mc-watch-row,
.mc-region-row,
.mc-out-row,
.mc-change {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 6px;
  border-bottom: 1px solid var(--mc-line);
  min-width: 0;
  transition: background 0.15s;
}
.mc-queue-row:hover,
.mc-task-row:hover,
.mc-watch-row:hover,
.mc-region-row:hover,
.mc-out-row:hover,
.mc-change:hover {
  background: color-mix(in srgb, var(--mc-panel2) 70%, transparent);
}
.mc-out-row {
  justify-content: space-between;
}
.mc-change {
  align-items: flex-start;
}
.mc-change svg {
  flex: none;
  margin-top: 2px;
}
.mc-step {
  display: flex;
  gap: 10px;
  align-items: flex-start;
  padding: 6px 0;
}
.mc-step-n {
  width: 30px;
  height: 30px;
  flex: none;
  border-radius: 9px;
  display: grid;
  place-items: center;
  color: var(--mc-accent);
  background: color-mix(in srgb, var(--mc-accent) 13%, transparent);
}
.mc-steps {
  display: flex;
  gap: 4px;
  align-items: center;
  flex-wrap: wrap;
}
.mc-steps > * {
  flex: 1 1 0;
}
.mc-timeline {
  display: flex;
  flex-direction: column;
  gap: 0;
  position: relative;
  padding-left: 14px;
  border-left: 2px solid var(--mc-line2);
}
.mc-tl-item {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 6px 0 8px 8px;
}
.mc-tl-item::before {
  content: "";
  position: absolute;
  left: -21px;
  top: 10px;
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--mc-accent);
  box-shadow: 0 0 0 3px var(--mc-panel);
}
.mc-tl-date {
  color: var(--mc-muted);
  font-size: 0.8em;
}
.mc-compare {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: var(--mc-gap);
}
.mc-win {
  color: var(--mc-good);
  font-weight: 700;
}
.mc-export {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.mc-doc {
  padding: 18px 22px;
  border-radius: 12px;
  background: var(--mc-panel2);
  border: 1px solid var(--mc-line);
  line-height: 1.6;
}
.mc-doc h2 {
  font-size: 1.2em;
  margin-bottom: 6px;
}
.mc-doc h3 {
  font-size: 1em;
  color: var(--mc-accent);
  margin: 12px 0 4px;
}
.mc-matrix {
  display: grid;
  gap: 4px;
  font-size: 0.85em;
}
.mc-quick-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 8px;
}
.mc-quick {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 12px 6px;
  border-radius: 12px;
  border: 1px solid var(--mc-line);
  background: var(--mc-panel2);
  cursor: pointer;
  font-size: 0.86em;
  transition: transform 0.22s cubic-bezier(0.34, 1.56, 0.64, 1), border-color 0.2s, background 0.2s;
}
.mc-quick svg {
  color: var(--mc-accent);
}
.mc-quick:hover {
  transform: translateY(-3px);
  border-color: color-mix(in srgb, var(--mc-accent) 45%, transparent);
  background: color-mix(in srgb, var(--mc-accent) 8%, var(--mc-panel2));
}
.mc-crisis-art {
  display: grid;
  place-items: center;
  padding: 8px;
}
.mc-crisis-art svg {
  color: var(--mc-bad);
  filter: drop-shadow(0 0 14px var(--mc-bad));
}
.mc-ticker {
  overflow: hidden;
  border-radius: 10px;
  border: 1px solid var(--mc-line);
  background: var(--mc-panel);
  mask-image: linear-gradient(90deg, transparent, #000 6%, #000 94%, transparent);
}
.mc-ticker-track {
  display: inline-flex;
  gap: 28px;
  padding: 9px 0;
  white-space: nowrap;
  animation: mc-marquee 60s linear infinite;
}
.mc-ticker-track:hover {
  animation-play-state: paused;
}
.mc-tick {
  display: inline-flex;
  gap: 6px;
  align-items: center;
}
.mc-up {
  color: var(--mc-good);
}
.mc-down {
  color: var(--mc-bad);
}
.mc-mini-cal {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 3px;
  text-align: center;
  font-size: 0.82em;
}
.mc-mini-dow {
  color: var(--mc-muted);
  font-size: 0.8em;
  padding-bottom: 2px;
}
.mc-mini-day {
  position: relative;
  height: 26px;
  border: 0;
  border-radius: 7px;
  background: transparent;
  cursor: pointer;
  color: var(--mc-soft);
  transition: background 0.15s;
}
.mc-mini-day:hover {
  background: var(--mc-panel2);
}
.mc-mini-day.mc-has::after {
  content: "";
  position: absolute;
  left: 50%;
  bottom: 3px;
  width: 4px;
  height: 4px;
  margin-left: -2px;
  border-radius: 50%;
  background: var(--mc-accent);
}
.mc-mini-day.mc-today {
  background: var(--mc-accent);
  color: #111;
  font-weight: 700;
}
.mc-mission-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: var(--mc-gap);
}
.mc-mission-card {
  display: flex;
  gap: 12px;
  align-items: center;
  padding: 12px;
  border-radius: 12px;
  border: 1px solid var(--mc-line);
  background: var(--mc-panel2);
  cursor: pointer;
  transition: transform 0.22s cubic-bezier(0.34, 1.56, 0.64, 1), border-color 0.2s;
}
.mc-mission-card:hover {
  transform: translateY(-2px);
  border-color: var(--mc-line2);
}
.mc-mission-line {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  font-size: 0.86em;
  padding: 3px 0;
}
.mc-mission-mini {
  display: flex;
  gap: 14px;
  align-items: center;
}
.mc-kanban {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: var(--mc-gap);
  align-items: start;
}
.mc-kanban-3 {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}
.mc-lane {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 10px;
  border-radius: 12px;
  background: var(--mc-bg2);
  border: 1px solid var(--mc-line);
  min-height: 160px;
  max-height: 620px;
  overflow-y: auto;
  transition: border-color 0.2s, background 0.2s;
}
.mc-lane.mc-drop {
  background: color-mix(in srgb, var(--mc-accent) 7%, var(--mc-bg2));
}
.mc-lane-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-weight: 600;
  color: var(--mc-soft);
  padding: 0 2px 4px;
  position: sticky;
  top: -10px;
  background: var(--mc-bg2);
  z-index: 1;
}
.mc-lane-empty {
  padding: 18px;
  text-align: center;
  color: var(--mc-muted);
  border: 1px dashed var(--mc-line2);
  border-radius: 10px;
  font-size: 0.86em;
}
.mc-kcard {
  display: flex;
  flex-direction: column;
  gap: 5px;
  padding: 10px;
  border-radius: 10px;
  background: var(--mc-panel);
  border: 1px solid var(--mc-line);
  cursor: grab;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.15);
  transition: transform 0.2s cubic-bezier(0.34, 1.56, 0.64, 1), border-color 0.2s, box-shadow 0.2s;
  animation: mc-pop 0.3s cubic-bezier(0.22, 1, 0.36, 1) both;
}
.mc-kcard:hover {
  transform: translateY(-2px);
  border-color: var(--mc-line2);
  box-shadow: 0 8px 18px rgba(0, 0, 0, 0.25);
}
.mc-kcard:active {
  cursor: grabbing;
}
.mc-kcard-late {
  border-left: 3px solid var(--mc-bad);
}
.mc-gantt {
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.mc-gantt-axis {
  position: relative;
  height: 22px;
  margin-left: 240px;
  margin-right: 250px;
  color: var(--mc-muted);
  font-size: 0.78em;
  border-bottom: 1px solid var(--mc-line);
}
.mc-gantt-axis span {
  position: absolute;
  top: 2px;
  transform: translateX(-50%);
  white-space: nowrap;
}
.mc-gantt-row {
  display: grid;
  grid-template-columns: 240px 1fr 250px;
  gap: 0;
  align-items: center;
  min-height: 34px;
  border-radius: 8px;
  transition: background 0.15s;
}
.mc-gantt-row:hover {
  background: var(--mc-panel2);
}
.mc-gantt-label {
  display: flex;
  flex-direction: column;
  padding: 0 10px;
  overflow: hidden;
}
.mc-gantt-label b {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.mc-gantt-track {
  position: relative;
  height: 24px;
}
.mc-gantt-bar {
  position: absolute;
  top: 5px;
  height: 14px;
  border-radius: 7px;
  background: color-mix(in srgb, currentColor 25%, var(--mc-panel3));
  border: 1px solid color-mix(in srgb, currentColor 60%, transparent);
  overflow: hidden;
  transform-origin: left;
  animation: mc-grow-x 0.7s cubic-bezier(0.22, 1, 0.36, 1) both;
}
.mc-gantt-fill {
  height: 100%;
  background: currentColor;
  opacity: 0.85;
}
.mc-gantt-milestone {
  position: absolute;
  top: 6px;
  width: 11px;
  height: 11px;
  margin-left: -5px;
  transform: rotate(45deg);
  background: var(--mc-accent);
  border: 1px solid var(--mc-bg);
}
.mc-gantt-today {
  position: absolute;
  top: 0;
  bottom: 0;
  width: 2px;
  background: var(--mc-bad);
  opacity: 0.7;
}
.mc-gantt-meta {
  display: flex;
  gap: 6px;
  justify-content: flex-end;
  align-items: center;
  padding: 0 8px;
}
.mc-gantt-meta .mc-small {
  min-width: 64px;
  text-align: right;
  white-space: nowrap;
}
.mc-cal-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 280px;
  gap: var(--mc-gap);
  align-items: start;
}
.mc-cal-main {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.mc-cal-side {
  display: flex;
  flex-direction: column;
  gap: var(--mc-gap);
}
.mc-cal-nav {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}
.mc-cal-label {
  font-weight: 700;
  font-size: 1.15em;
  min-width: 160px;
  text-align: center;
}
.mc-cal-month {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 4px;
}
.mc-cal-dow {
  color: var(--mc-muted);
  font-size: 0.78em;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  padding: 4px 6px;
}
.mc-cal-cell {
  min-height: 96px;
