  padding: 10px 6px;
  border-bottom: 1px solid var(--mc-line);
  align-items: flex-start;
  animation: mc-pop 0.25s cubic-bezier(0.22, 1, 0.36, 1) both;
}
.mc-notif-row.mc-notif-unread {
