  gap: 14px;
  padding: 40px 60px;
  border-radius: 18px;
  outline: none;
  background: radial-gradient(80% 80% at 80% 20%, color-mix(in srgb, var(--mc-accent) 14%, transparent), transparent 60%), var(--mc-panel);
  border: 1px solid var(--mc-line);
}
.mc-story-step {
  color: var(--mc-muted);
  letter-spacing: 0.12em;
}
.mc-story-title {
  font-size: 2em;
