  animation: mc-rise 0.5s cubic-bezier(0.22, 1, 0.36, 1) both;
}
.mc-story-kpi {
  font-size: 3em;
  font-weight: 800;
  color: var(--mc-accent);
  animation: mc-rise 0.5s 0.06s cubic-bezier(0.22, 1, 0.36, 1) both;
}
.mc-story-text {
  font-size: 1.12em;
  color: var(--mc-soft);
  max-width: 760px;
  animation: mc-rise 0.5s 0.12s cubic-bezier(0.22, 1, 0.36, 1) both;
}
.mc-story-dots {
  display: flex;
  gap: 6px;
}
.mc-story-dots button {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  border: 0;
  background: var(--mc-panel3);
