}
.mc-tm-track {
  position: relative;
  padding: 14px 0 4px;
}
.mc-tm-marks {
  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  height: 12px;
}
.mc-tm-mark {
  position: absolute;
  top: 2px;
  width: 3px;
  height: 9px;
  border-radius: 2px;
  opacity: 0.8;
}
.mc-tm-mark-alert {
  top: 0;
  height: 5px;
}
.mc-tm-ends {
  display: flex;
  justify-content: space-between;
  color: var(--mc-muted);
  font-size: 0.8em;
}
.mc-tm-tile {
  padding: 10px 12px;
  border-radius: 10px;
  border: 1px solid var(--mc-line);
  background: var(--mc-panel2);
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.mc-tm-tile b {
  font-size: 1.3em;
}
.mc-tilemap {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  grid-auto-rows: 70px;
  gap: 8px;
  max-width: 460px;
  margin: 0 auto;
}
.mc-tile {
  --mc-int: 0.5;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: 2px;
  border-radius: 14px;
  cursor: pointer;
  border: 1px solid color-mix(in srgb, var(--mc-accent) 50%, transparent);
  color: var(--mc-text);
  background: color-mix(in srgb, var(--mc-accent) calc(var(--mc-int) * 70%), var(--mc-panel2));
  transition: transform 0.22s cubic-bezier(0.34, 1.56, 0.64, 1), box-shadow 0.22s;
}
.mc-tile span {
  font-size: 0.82em;
}
.mc-tile:hover {
  transform: scale(1.05);
  box-shadow: 0 0 20px color-mix(in srgb, var(--mc-accent) 40%, transparent);
}
.mc-tile.mc-on {
  box-shadow: 0 0 0 2px var(--mc-text), 0 0 24px var(--mc-accent);
}
.mc-overlay {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 50;
}
.mc-overlay > * {
  pointer-events: auto;
}
.mc-overlay:empty {
  display: none;
}
.mc-veil {
  position: absolute;
  inset: 0;
  background: rgba(0, 0, 0, 0.45);
  backdrop-filter: blur(3px);
  animation: mc-fade 0.22s ease both;
}
.mc-drawer {
  position: absolute;
  top: 0;
  right: 0;
  bottom: 0;
  width: 440px;
  max-width: 92%;
  display: flex;
  flex-direction: column;
  background: var(--mc-panel);
  border-left: 1px solid var(--mc-line2);
  box-shadow: -20px 0 50px rgba(0, 0, 0, 0.4);
  animation: mc-slide-in 0.36s cubic-bezier(0.22, 1, 0.36, 1) both;
}
.mc-drawer-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 14px 16px;
  border-bottom: 1px solid var(--mc-line);
}
.mc-drawer-title {
  display: flex;
  align-items: center;
  gap: 8px;
  font-weight: 700;
  font-size: 1.05em;
}
.mc-drawer-title svg {
  color: var(--mc-accent);
}
.mc-drawer-body {
  flex: 1;
  overflow-y: auto;
  padding: 14px 16px 22px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.mc-modal {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 620px;
  max-width: 92%;
  max-height: 86%;
  display: flex;
  flex-direction: column;
  transform: translate(-50%, -50%);
  border-radius: 18px;
  background: var(--mc-panel);
  border: 1px solid var(--mc-line2);
  box-shadow: 0 30px 80px rgba(0, 0, 0, 0.5);
  animation: mc-modal-in 0.32s cubic-bezier(0.34, 1.56, 0.64, 1) both;
}
.mc-modal-head {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 14px 16px;
  border-bottom: 1px solid var(--mc-line);
  font-weight: 700;
}
.mc-modal-head svg {
  color: var(--mc-accent);
}
.mc-modal-head .mc-icon-btn {
  margin-left: auto;
}
.mc-modal-body {
  padding: 16px;
  overflow-y: auto;
}
.mc-modal-actions {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  padding: 12px 16px;
  border-top: 1px solid var(--mc-line);
}
.mc-form {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}
.mc-form-field {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.mc-form-field .mc-input,
.mc-form-field .mc-select,
.mc-form-field select {
  width: 100%;
}
.mc-wide {
  grid-column: 1 / -1;
}
.mc-palette {
  position: absolute;
  left: 50%;
  top: 70px;
  width: 680px;
  max-width: 92%;
  transform: translateX(-50%);
  border-radius: 16px;
  background: var(--mc-panel);
  border: 1px solid var(--mc-line2);
  box-shadow: 0 30px 80px rgba(0, 0, 0, 0.55), 0 0 0 1px color-mix(in srgb, var(--mc-accent) 20%, transparent);
  overflow: hidden;
  animation: mc-palette-in 0.26s cubic-bezier(0.34, 1.56, 0.64, 1) both;
}
.mc-palette-head {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 14px;
  border-bottom: 1px solid var(--mc-line);
}
.mc-palette-head svg {
  color: var(--mc-accent);
}
.mc-palette-input {
  flex: 1;
  border: 0;
  outline: none;
  background: transparent;
  color: var(--mc-text);
  font: inherit;
  font-size: 1.1em;
}
.mc-palette-list {
  max-height: 420px;
  overflow-y: auto;
  padding: 6px;
}
.mc-palette-row {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 10px;
  border-radius: 9px;
  cursor: pointer;
}
.mc-palette-row svg {
  color: var(--mc-soft);
  flex: none;
}
.mc-palette-row.mc-on {
  background: color-mix(in srgb, var(--mc-accent) 14%, transparent);
}
.mc-palette-row.mc-on svg {
  color: var(--mc-accent);
}
.mc-palette-text {
  flex: 1;
  min-width: 0;
}
.mc-palette-text > div {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.mc-palette-sub {
  color: var(--mc-muted);
  font-size: 0.82em;
}
.mc-palette-empty {
  display: flex;
  gap: 8px;
  align-items: center;
  padding: 18px;
  color: var(--mc-muted);
}
.mc-palette-recent {
  display: flex;
  gap: 10px;
  align-items: center;
  padding: 8px 14px;
  font-size: 0.85em;
  color: var(--mc-muted);
  border-bottom: 1px solid var(--mc-line);
}
.mc-palette-foot {
  padding: 8px 14px;
  font-size: 0.78em;
  color: var(--mc-muted);
  border-top: 1px solid var(--mc-line);
}
.mc-toast {
  position: absolute;
  z-index: 80;
  right: 20px;
  bottom: 20px;
  display: flex;
  align-items: center;
  gap: 10px;
  max-width: 460px;
  padding: 11px 14px;
  border-radius: 12px;
  background: var(--mc-panel2);
  border: 1px solid var(--mc-line2);
  color: var(--mc-text);
  box-shadow: var(--mc-shadow);
  animation: mc-toast-in 0.4s cubic-bezier(0.34, 1.56, 0.64, 1) both;
}
.mc-toast.mc-tone-good svg {
  color: var(--mc-good);
}
.mc-toast.mc-tone-bad svg {
  color: var(--mc-bad);
}
.mc-toast.mc-tone-info svg {
  color: var(--mc-info);
}
.mc-toast-out {
  animation: mc-toast-out 0.28s ease both;
}
.mc-pulse {
  position: relative;
  animation: mc-pulse 2.4s ease-in-out infinite;
}
@keyframes mc-rise {
  from {
    opacity: 0;
    transform: translateY(10px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
@keyframes mc-fade {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}
@keyframes mc-pop {
  from {
    opacity: 0;
    transform: scale(0.97) translateY(4px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
@keyframes mc-slide-in {
  from {
    transform: translateX(100%);
    opacity: 0.4;
  }
  to {
    transform: none;
    opacity: 1;
  }
}
@keyframes mc-modal-in {
  from {
    opacity: 0;
    transform: translate(-50%, -46%) scale(0.96);
  }
  to {
    opacity: 1;
    transform: translate(-50%, -50%);
  }
}
@keyframes mc-palette-in {
  from {
    opacity: 0;
    transform: translate(-50%, -10px) scale(0.98);
  }
  to {
    opacity: 1;
    transform: translateX(-50%);
  }
}
@keyframes mc-toast-in {
  from {
    opacity: 0;
    transform: translateY(16px) scale(0.96);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
@keyframes mc-toast-out {
  to {
    opacity: 0;
    transform: translateY(10px);
  }
}
@keyframes mc-dash {
  from {
    stroke-dashoffset: var(--mc-from);
  }
  to {
    stroke-dashoffset: var(--mc-to);
  }
}
@keyframes mc-draw {
  from {
    stroke-dashoffset: 600;
  }
  to {
    stroke-dashoffset: 0;
  }
}
@keyframes mc-grow-x {
  from {
    transform: scaleX(0);
  }
  to {
    transform: scaleX(1);
  }
}
@keyframes mc-shimmer {
  from {
    background-position: 200% 0;
  }
  to {
    background-position: -200% 0;
  }
}
@keyframes mc-flow {
  to {
    stroke-dashoffset: -24;
  }
}
@keyframes mc-spin {
  to {
    transform: rotate(360deg);
  }
}
@keyframes mc-marquee {
  from {
    transform: translateX(0);
  }
  to {
    transform: translateX(-50%);
  }
}
@keyframes mc-wiggle {
  0%,
  100% {
    transform: none;
  }
  50% {
    transform: scale(0.99);
  }
}
@keyframes mc-pulse {
  0%,
  100% {
    box-shadow: 0 0 0 0 color-mix(in srgb, var(--mc-bad) 0%, transparent);
  }
  50% {
    box-shadow: 0 0 0 4px color-mix(in srgb, var(--mc-bad) 28%, transparent);
  }
}
.mc-reduced,
.mc-reduced * {
  animation: none !important;
  transition: none !important;
}
@media (prefers-reduced-motion: reduce) {
  .mc-app,
  .mc-app * {
    animation: none !important;
    transition: none !important;
    scroll-behavior: auto !important;
  }
}
.mc-table-tools .mc-search-box,
.mc-filters .mc-search-box {
  flex: 1 1 220px;
}
.mc-card-body > .mc-seg,
.mc-card-body > .mc-btn,
.mc-card-body > .mc-tabs,
.mc-card-body > .mc-field {
  align-self: flex-start;
}
.mc-feed-alert {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 7px 16px;
  flex: none;
  font-size: 0.88em;
  color: var(--mc-text);
  background: color-mix(in srgb, var(--mc-warn) 16%, var(--mc-bg2));
  border-bottom: 1px solid color-mix(in srgb, var(--mc-warn) 45%, transparent);
}
.mc-feed-alert svg {
  color: var(--mc-warn);
  flex: none;
}
